\documentclass{article}
\usepackage{pgfplots}
\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
\definecolor{rustred}{rgb}{0.784,0.392,0.149}
\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

\begin{document}

	\pagestyle{empty} %% IMPORTANT

	\begin{tikzpicture}[scale = 1.0]
	\def\gcolor{deepskyblue}

\begin{axis}[
legend pos=outer north east,
tick label style={font=\footnotesize},
label style={font=\small},
y tick label style = {xshift=20pt},
tick style={line width=0.8pt, color=black},
axis line style = thick,
axis y line = center,
axis x line = middle,
axis equal,
xmin = -7,
xmax = 2,
ymin = -1.8,
ymax = 1.8,
xtick = {-20,20},
%minor xtick={-11,-9,-7,-5,-3,-1,1,3,5,7,9,11},
ytick = {-20,20},
%minor ytick={-9,-7,-5,-3,-1,1,3,5,7,9,11},    
xlabel = $x$,
ylabel = {$y$},
xlabel style={below right},
ylabel style={above left},
every axis x label/.style={
	at={(ticklabel* cs:1.02)},
	anchor=west,
},
every axis y label/.style={
	at={(ticklabel* cs:1.02)},
	anchor=south,
}
]
%\node[circle,color=red,fill,inner sep=2pt] at (axis cs:-2,-4) {};
%\node[label={-90:{$(-2,-4)$}}] at (axis cs:-4.5,-3) {};

\addplot [
domain=-10:10,
samples=300,
color=\gcolor,
line width=1pt,
]{abs(x+4)-1};

\addplot [domain=-7:10,samples=200,color=black,line width=0.6pt,dashed,opacity=0.7]{abs(x)};

\node[circle,\gcolor,fill,inner sep=1.2pt] (A) at (axis cs: -4,-1) {};
\node[circle,black,fill,inner sep=1.2pt] (A) at (axis cs: 0,0) {};

\draw[->, \gcolor, line width=0.7pt, dashed, opacity=0.7] (axis cs:-0.2,0.15) -- (axis cs:-3.9,0.15);
\node[below] at (axis cs: -2,0.7) {\footnotesize{$\color{\gcolor}4$}};
\draw[->, \gcolor, line width=0.7pt, dashed, opacity=0.7] (axis cs:-4,0.15) -- (axis cs:-4,-0.8);
\node[left] at (axis cs: -4,-0.35) {\footnotesize{$\color{\gcolor}1$}};

\node[circle,color=\gcolor,fill,label={-90:{$(-4,-1)$}},inner sep=1.2pt] at (axis cs:-4,-1) {};


\end{axis}

\end{tikzpicture}
\end{document}

